const crypto = require('crypto');
const item = $input.first();
const headers = item.json && item.json.headers && typeof item.json.headers === 'object' ? item.json.headers : {};
const getHeader = (name) => {
  const wanted = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === wanted) return Array.isArray(value) ? value[0] : value;
  }
  return undefined;
};
const timestampText = String(getHeader('x-delivery-timestamp') ?? '');
const signature = String(getHeader('x-delivery-signature') ?? '');
const secret = String($env.N8N_WEBHOOK_SECRET ?? '').trim();
const encoded = item.binary && item.binary.data && item.binary.data.data;
const base64 = typeof encoded === 'string' ? encoded : '';
let raw = null;
if (base64 && /^[A-Za-z0-9+/]*={0,2}$/.test(base64) && base64.length % 4 === 0) {
  const candidate = Buffer.from(base64, 'base64');
  if (candidate.toString('base64') === base64) raw = candidate;
}
const timestamp = /^-?\d+$/.test(timestampText) ? Number(timestampText) : Number.NaN;
const now = Math.floor(Date.now() / 1000);
let authOk = false;
if (secret && raw && Number.isSafeInteger(timestamp) && Math.abs(now - timestamp) <= 300 && /^sha256=[0-9a-f]{64}$/.test(signature)) {
  const expected = crypto.createHmac('sha256', secret).update(`${timestampText}.`).update(raw).digest();
  const supplied = Buffer.from(signature.slice(7), 'hex');
  authOk = supplied.length === expected.length && crypto.timingSafeEqual(supplied, expected);
}
let body = null;
let bodyOk = false;
if (authOk) {
  try {
    const text = new TextDecoder('utf-8', { fatal: true }).decode(raw);
    const parsed = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      body = parsed;
      bodyOk = true;
    }
  } catch {}
}
return [{ json: { auth_ok: authOk, body_ok: bodyOk, body } }];

const envelope = $input.first().json || {};
const payload = envelope.body;
const nonBlank = (value) => typeof value === 'string' && value.trim().length > 0;
const emailAddress = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const exactKeys = ['action_code', 'action_id', 'approval_id', 'chamber_id', 'channel', 'email_kind', 'lot_id', 'recipients', 'request_hash', 'schema', 'summary'];
const keysOk = payload && typeof payload === 'object' && !Array.isArray(payload) && Object.keys(payload).sort().join('\u0000') === exactKeys.join('\u0000');
const combinationOk = payload && ((payload.action_code === 'WARNING' && payload.email_kind === 'WARNING_NOTIFY') || (payload.action_code === 'EQP_HOLD' && payload.email_kind === 'APPROVAL_REQUEST'));
const approvalOk = payload && (payload.email_kind === 'APPROVAL_REQUEST' ? nonBlank(payload.approval_id) : payload.approval_id === null);
const recipientsOk = payload && Array.isArray(payload.recipients) && payload.recipients.length > 0 && payload.recipients.every((value) => nonBlank(value) && emailAddress.test(value));
const summaryOk = payload && nonBlank(payload.summary) && payload.summary.length <= 2000 && !/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(payload.summary);
const schemaOk = envelope.body_ok === true && keysOk && payload.schema === 'email-request-v1' && nonBlank(payload.action_id) && payload.channel === 'EMAIL' && combinationOk && /^([0-9a-f]{64})$/.test(payload.request_hash) && recipientsOk && nonBlank(payload.lot_id) && nonBlank(payload.chamber_id) && summaryOk && approvalOk;
return [{ json: { schema_ok: schemaOk, payload: schemaOk ? payload : null } }];

const crypto = require('crypto');
const payload = $('Validate Email Payload').first().json.payload;
const result = $input.first().json || {};
const providerId = typeof result.messageId === 'string' && result.messageId.trim() ? result.messageId.trim() : null;
const sendFailed = Object.prototype.hasOwnProperty.call(result, 'error');
const status = !sendFailed && providerId ? 'SENT' : 'FAILED';
const errorCode = status === 'SENT' ? null : (sendFailed ? 'SMTP_SEND_FAILED' : 'SMTP_MESSAGE_ID_MISSING');
const secret = String($env.N8N_WEBHOOK_SECRET ?? '').trim();
const rawBaseUrl = String($env.BACKEND_BASE_URL ?? '').trim();
let baseUrl = null;
try {
  const parsed = new URL(rawBaseUrl);
  if ((parsed.protocol === 'http:' || parsed.protocol === 'https:') && !parsed.username && !parsed.password) baseUrl = rawBaseUrl.replace(/\/+$/, '');
} catch {}
if (!secret || !baseUrl) return [{ json: { config_ok: false } }];
const timestamp = String(Math.floor(Date.now() / 1000));
const callback = {
  event_id: `WF2:${payload.action_id}:EMAIL:${payload.request_hash}:${status}`,
  channel: 'EMAIL',
  status,
  provider_message_id: providerId,
  request_hash: payload.request_hash,
  completed_at: new Date().toISOString(),
  error_code: errorCode
};
const callbackRawBody = JSON.stringify(callback);
const signature = `sha256=${crypto.createHmac('sha256', secret).update(`${timestamp}.${callbackRawBody}`, 'utf8').digest('hex')}`;
return [{ json: { config_ok: true, callback_raw_body: callbackRawBody, callback_url: `${baseUrl}/internal/actions/${encodeURIComponent(payload.action_id)}/delivery`, callback_timestamp: timestamp, callback_signature: signature } }];

const result = $input.first().json || {};
const statusCode = Number(result.statusCode);
const callbackOk = Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300;
return [{ json: { callback_ok: callbackOk, status_code: Number.isInteger(statusCode) ? statusCode : null } }];
